sksl:
uniform shader image;
uniform shader blurred;
uniform float2 size;
uniform float time;
uniform float blur;
uniform float intensity;
uniform float falloff;
uniform float opacity;
uniform float original;
uniform float outside;
uniform float saturation;
uniform float vibrance;
uniform float hue;
layout(color) uniform half4 tint;
uniform float tintAmount;
uniform float limit;
uniform float low;
uniform float high;
uniform float softness;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float4 pick(float2 p) {
    float4 g = float4(blurred.eval(p));
    if (limit > 0.5) {
        float l = g.a > 0.0 ? luma(g.rgb / g.a) : 0.0;
        float f = max(softness, 0.001);
        g *= smoothstep(low - f, low, l) * (1.0 - smoothstep(high, high + f, l));
    }
    return g;
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    float reach = max(blur, 0.0) * 2.5;
    float span = mix(2.5, 0.3, clamp(falloff, 0.0, 1.0));
    float3 sum = pick(coord).rgb * 16.0;
    float total = 16.0;
    float2 d = float2(1.0, 0.0);
    for (int i = 0; i < 48; i++) {
        float u = sqrt((float(i) + 0.5) / 48.0);
        float w = exp(-2.5 * u / span);
        sum += w * pick(coord + d * u * reach).rgb;
        total += w;
        d = float2(d.x * -0.7373688 - d.y * 0.6754903, d.x * 0.6754903 + d.y * -0.7373688);
    }
    float3 g = sum / total;
    float turn = radians(hue);
    float3 k = float3(0.57735);
    g = max(g * cos(turn) + cross(k, g) * sin(turn) + k * dot(k, g) * (1.0 - cos(turn)), 0.0);
    float top = max(g.r, max(g.g, g.b));
    float chroma = top > 0.0 ? (top - min(g.r, min(g.g, g.b))) / top : 0.0;
    float y = luma(g);
    g = max(float3(y) + (g - float3(y)) * (1.0 + saturation) * (1.0 + vibrance * (1.0 - chroma)), 0.0);
    g = mix(g, luma(g) * float3(tint.rgb), clamp(tintAmount, 0.0, 1.0) * float(tint.a));
    float3 light = (1.0 - exp(-g * max(intensity, 0.0) * 4.0)) * clamp(opacity, 0.0, 1.0);
    light *= mix(clamp(outside, 0.0, 1.0), 1.0, float(c.a));
    float4 base = float4(c) * clamp(original, 0.0, 1.0);
    float a = base.a + (1.0 - base.a) * max(light.r, max(light.g, light.b));
    float3 rgb = base.rgb + light - base.rgb * light;
    return half4(half3(clamp(rgb, 0.0, a)), half(a));
}
